const body = $input.item.json.body;

if (!body) return [];

const from = body.phone || '';
const messageText = body.text?.message || '';

if (!from || !messageText) return [];

return [{
  json: {
    telefone: from,
    message: messageText,
    messageType: 'text',
    instanceName: 'hormone-clinica'
  }
}];

const leads = $input.item.json;
const telefone = $('Extrair Mensagem').item.json.telefone;
const message = $('Extrair Mensagem').item.json.message;

let lead = Array.isArray(leads) ? leads[0] : null;
let isNew = false;

if (!lead) {
  isNew = true;
  lead = {
    telefone: telefone,
    etapa_agente: 1,
    temperatura: 'morno',
    historico: [],
    dor_principal: null,
    nome: null
  };
}

const historico = lead.historico || [];
// Adiciona mensagem do usuário UMA VEZ aqui — Processar Resposta NÃO deve adicionar novamente
historico.push({ role: 'user', content: message, ts: new Date().toISOString() });

return [{
  json: {
    ...lead,
    telefone,
    message,
    isNew,
    historico
  }
}];

// FIX 2: parseInt em etapa_agente evita bug '1'+1='11' → Math.min(8,'11',8)=8
// FIX 3: NÃO adicionar mensagem do usuário aqui — Processar Lead já fez isso
const claudeResponse = $input.item.json;
const lead = $('Montar Prompt').item.json;

let resposta = '';
let proximaEtapa = parseInt(lead.etapa_agente) || 1;
let dorPrincipal = lead.dor_principal;
let nomeLead = lead.nome;

try {
  let content = claudeResponse.content?.[0]?.text || '';
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON found');
  const parsed = JSON.parse(jsonMatch[0]);
  resposta = parsed.resposta || content;
  resposta = resposta.replace(/\n/g, ' ').replace(/\r/g, '').trim();
  const etapaAtual = parseInt(lead.etapa_agente) || 1;
  const etapaSugerida = parseInt(parsed.proxima_etapa) || etapaAtual;
  // Cap: avança no máximo 1 etapa por vez, nunca passa de 8
  proximaEtapa = Math.min(Math.max(etapaSugerida, etapaAtual), etapaAtual + 1, 8);
  if (parsed.dor_principal) dorPrincipal = parsed.dor_principal;
  if (parsed.nome_lead) nomeLead = parsed.nome_lead;
} catch (e) {
  const etapaAtual = parseInt(lead.etapa_agente) || 1;
  proximaEtapa = etapaAtual;
  let raw = claudeResponse.content?.[0]?.text || 'Desculpe, tive um problema. Pode repetir?';
  resposta = raw.replace(/\s*\{[\s\S]*\}\s*$/i, '').replace(/\n/g, ' ').replace(/\r/g, '').trim();
  if (!resposta) resposta = 'Desculpe, tive um problema. Pode repetir?';
}

const historico = lead.historico || [];
// Adiciona SOMENTE a resposta do assistente — usuário já foi adicionado em Processar Lead
historico.push({ role: 'assistant', content: resposta, ts: new Date().toISOString() });

return [{ json: { ...lead, resposta, proximaEtapa, dorPrincipal, nomeLead, historico } }];

// FIX 4: PATCH por id=eq.{leadId} em vez de telefone=eq.{telefone}
// O telefone no Supabase pode ter formato diferente do recebido pelo webhook
// causando 0 rows afetadas silenciosamente
const SUPABASE_URL = 'https://rmsblsoqqhtantyomhsh.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJtc2Jsc29xcWh0YW50eW9taHNoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODA4OTI5MDgsImV4cCI6MjA5NjQ2ODkwOH0.PAje_eA_dYrwM_5f-4n9MMDY-GGtC0ZzEdRn7W3gg30';

const data = $input.item.json;
const telefone = $('Extrair Mensagem').item.json.telefone;
const leadId = data.id;

const body = {
  telefone: telefone,
  nome: data.nomeLead || data.nome || null,
  etapa_agente: data.proximaEtapa || data.proxima_etapa || 1,
  dor_principal: data.dorPrincipal || data.dor_principal || null,
  historico: data.historico || [],
  temperatura: data.temperatura || 'morno',
  origem_agente: 'whatsapp'
};

try {
  if (data.isNew) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/leads`,
      headers: {
        'Content-Type': 'application/json',
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + SUPABASE_KEY,
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify(body),
    });
  } else {
    // PATCH por ID — garante que a linha certa é atualizada
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/leads?id=eq.${leadId}`,
      headers: {
        'Content-Type': 'application/json',
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + SUPABASE_KEY,
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify(body),
    });
  }
} catch(e) {
  console.error('Erro ao salvar lead:', e.message);
}

return [{ json: { ...data, saved: true } }];
